findings.rationale:
name is request-controlled. A value such as ../../tmp/file makes os.Create write outside /var/uploads. This permits arbitrary file writes with the service account permissions.

Reject empty names, . and .., and names where `filepath.Base(name) != name. Return 400 Bad Request` for invalid names.

Proposed fix

import ( "fmt" "net/http" "os" +	"path/filepath" "sync" )

func (h *Handler) Upload(w http.ResponseWriter, r *http.Request) { name := r.URL.Query().Get("name") +	if name == "" || name == "." || name == ".." || filepath.Base(name) != name { +		http.Error(w, "invalid upload name", http.StatusBadRequest) +		return +	}

-	f, err := os.Create("/var/uploads/" + name) +	f, err := os.Create(filepath.Join("/var/uploads", name))
